P={p['id']:p for p in R['Patient']}
S={s['id']:s for s in R['Specimen']}
acc=collections.defaultdict(list)
for b in R['Basic']: acc[ext(b,'accession')].append(b)
def subj(r):
  for k in ('subject','patient','for'):
    if k in r and isinstance(r[k],dict) and 'reference' in r[k]: return r[k]['reference'].split('/')[-1]
byp=collections.defaultdict(lambda: collections.defaultdict(list))
for t in types:
  if t=='Patient': continue
  for r in R[t]:
    p=subj(r)
    if p: byp[p][t].append(r)
# also index specimens by label mrn/dob for cross patient
order=sorted(P)
sel=sys.argv[1:] or order
if len(sel)==2 and sel[0].isdigit():
    a,b=int(sel[0]),int(sel[1]); sel=order[a:b]
for pid in sel:
  pt=P[pid]; b=byp[pid]
  mrn=pt['identifier'][0]['value']; dob=pt['birthDate']
  print('#'*90)
  print(f"{pid} {pt['name'][0]['text']} mrn={mrn} dob={dob} {pt['gender']}")
  for e in b['EpisodeOfCare']: print(f"  EP {e['id']} dx={e['period']['start']}")
  for c in sorted(b['Condition'],key=lambda x:x['recordedDate']): print(f"  DX {c['recordedDate'][:10]} {c['code']['text']} [{c['id']}] rec={c.get('recorder',{}).get('display')}")
  for a in b['AllergyIntolerance']: print(f"  ALLERGY {ext(a,'event-time')[:10]} {a['code']['text']} {a.get('reaction',[{}])[0].get('manifestation',[{}])[0].get('text')} [{a['id']}]")
  for m in sorted(b['MedicationAdministration'],key=lambda x:x['effectiveDateTime']):
    print(f"  MED {m['effectiveDateTime'][:10]} {m['medicationCodeableConcept']['text']} {m['dosage']['text']} {m['status']} [{m['id']}] note={'; '.join(n['text'] for n in m.get('note',[]))}")
  for m in sorted(b['MedicationDispense'],key=lambda x:x['whenHandedOver']):
    print(f"  DISP {m['whenHandedOver'][:10]} {m['medicationCodeableConcept']['text']} qty={m.get('quantity',{}).get('value')} days={m.get('daysSupply',{}).get('value')} [{m['id']}] {m.get('dosageInstruction',[{}])[0].get('text')} note={'; '.join(n['text'] for n in m.get('note',[]))}")
  for o in sorted(b['Observation'],key=lambda x:x['effectiveDateTime']):
    sp=S.get(o.get('specimen',{}).get('reference','').split('/')[-1])
    a=o.get('identifier',[{}])[0].get('value'); bs=acc.get(a,[])
    line=f"  OBS {o['effectiveDateTime'][:10]} {o['code']['text']}: {o.get('valueString')} [{o['id']}] status={o['status']} issued={(o.get('issued') or '')[:10]} acc={a}"
    notes='; '.join(n['text'] for n in o.get('note',[]))
    if notes: line+=f" NOTE={notes}"
    print(line)
    if sp:
      tag='' if (ext(sp,'label-mrn')==mrn and ext(sp,'label-dob')==dob) else ' <<LABEL-MISMATCH'
      print(f"      SPEC[{sp['id']}] subj={subj(sp)} coll={sp['collection'].get('collectedDateTime','')[:10]} by={sp['collection'].get('collector',{}).get('display')} label={ext(sp,'label-name')}|{ext(sp,'label-mrn')}|{ext(sp,'label-dob')}{tag}")
    for bb in bs:
      tag='' if (ext(bb,'patient-mrn')==mrn and ext(bb,'patient-dob')==dob) else ' <<ACC-MISMATCH'
      print(f"      ACC[{bb['id']}] {ext(bb,'patient-name')}|{ext(bb,'patient-mrn')}|{ext(bb,'patient-dob')} recv={ext(bb,'received')[:10]} by={bb.get('author',{}).get('display')}{tag}")
  for d in sorted(b['DocumentReference'],key=lambda x:x['date']):
    print(f"  DOC {d['date'][:16]} [{d['id']}] {d['type']['text']} ({ext(d,'author-role')}) {d.get('author',[{}])[0].get('display')}:")
    for ln in d['description'].split('\n'):
      if ln.strip(): print('       | '+ln)
  for t in b['Task']:
    print(f"  ** REQUEST [{t['id']}] {t['code']['coding'][0]['code']} focus={t.get('focus',{}).get('reference')}: {t['description']}")
